from robot.utils.robottime import timestr_to_secs

from ute_common_admin.util import fail_if_resp_contains_fail
from .base import BaseInterface
from ..validators import IsString, IsOneOf
from ..converter import to_bool, to_int


class IPConnectivityInterface(BaseInterface):

    def test_ip_connectivity(self, remote_address, dscp, payload_size, source_address, timeout=120, alias="default"):
        """ TestIPConnectivity

        :param string remote_address: remoteAddress
        :param integer dscp: dscp
        :param integer payload_size: payloadSize
        :param string source_address: sourceAddress
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(remote_address)
        dscp = to_int(dscp)
        payload_size = to_int(payload_size)
        IsString().check(source_address)
        response = self.store.get(alias).execute_procedure(
            "testIpConnectivity", {"remoteAddress": remote_address, "dscp": dscp, "payloadSize": payload_size}, timeout)
        fail_if_resp_contains_fail(response)
        return response

    def start_ip_capture_file(self, measurement_point, uplane_capturing, password="", timeout=120, alias="default"):
        """ StartIPCaptureFile

        :param string measurement_point: "NE_Terminated" or "Transport_Interface"
        :param boolean uplane_capturing: uplaneCapturing
        :param string password: password
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsOneOf("NE_Terminated", "Transport_Interface").check(measurement_point)
        uplane_capturing = to_bool(uplane_capturing)
        IsString().check(password)
        self.store.get(alias).execute_procedure("startIPCaptureFile",
                                                {"measurementPoint": measurement_point, "uplaneCapturing": uplane_capturing, "password": password},
                                                timeout)

    def start_ip_capture_streaming(self, measurement_point, uplane_capturing, dst_mac_addr, egress_port_dn, timeout=120, alias="default"):
        """ StartIPCaptureStreaming

        :param string measurement_point: "NE_Terminated" or "Transport_Interface"
        :param boolean uplane_capturing: uplaneCapturing
        :param string dst_mac_addr: dstMacAddr
        :param string egress_port_dn: egressPortDN
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        IsOneOf("NE_Terminated", "Transport_Interface").check(measurement_point)
        uplane_capturing = to_bool(uplane_capturing)
        IsString().check(dst_mac_addr)
        IsString().check(egress_port_dn)
        self.store.get(alias).execute_procedure("startIPCaptureStreaming",
                                                {"measurementPoint": measurement_point, "uplaneCapturing": uplane_capturing,
                                                 "dstMacAddr": dst_mac_addr, "egressPortDN": egress_port_dn}, timeout)

    def stop_ip_capture_file(self, timeout=120, alias="default"):
        """ StopIPCaptureFile

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        self.store.get(alias).execute_procedure("stopIPCaptureFile", {}, timeout)

    def stop_ip_capture_streaming(self, timeout=120, alias="default"):
        """ StopIPCaptureStreaming

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        self.store.get(alias).execute_procedure("stopIPCaptureStreaming", {}, timeout)

    def generate_ip_capture_file(self, password="", timeout=120, alias="default"):
        """ GenerateIPCaptureFile

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        :param string password: Password used to authorize the procedure
        """
        timeout = timestr_to_secs(timeout)
        IsString().check(password)
        self.store.get(alias).execute_procedure("generateIPCaptureFile", {"password": password}, timeout)

    def cancel_file_generating(self, timeout=120, alias="default"):
        """ cancelFileGenerating

        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        self.store.get(alias).execute_procedure("cancelFileGenerating", {}, timeout)

    def download_ip_capture_file(self, target_file_name, timeout=120, alias="default"):
        """ downloadIPCaptureFile

        :param string target_file_name: target filename.
        :param float timeout: Time to wait for positive procedure result.
        :param string alias: Name of execution context.
        """
        timeout = timestr_to_secs(timeout)
        return self.store.get(alias).execute_infomodel_request("downloadIPCaptureFile", {}, timeout,
                                                               output_file_name=target_file_name)
